=You must return ONLY a valid JSON object — no markdown, no explanation.

Domain: {{ $json.domain }}
Row count: {{ $json.row_count }}
Columns available: {{ JSON.stringify($json.columns) }}
Dataset context: {{ $json.dataset_context }}

Classify every column into exactly one category:
- dimensions: categorical / text / ID columns
- measures: numeric columns suitable for aggregation
- time_fields: date, datetime, timestamp columns

Also produce:
- analytical_richness_score (integer 0-100)
- warnings (array of data quality strings)

Return this exact JSON shape and nothing else:
{
  "dimensions": [],
  "measures": [],
  "time_fields": [],
  "analytical_richness_score": 0,
  "warnings": []
}

parameters.jsCode:
// Agent 1 output arrives in $json.output as a string
const raw = $input.first().json.output || '';
let parsed = {};
try {
  // Strip accidental markdown fences if the model adds them
  const cleaned = raw.replace(/```json?\n?/gi, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    dimensions: [],
    measures: [],
    time_fields: [],
    analytical_richness_score: 50,
    warnings: ['Agent 1 parse error: ' + e.message]
  };
}

const prev = $('Normalize Input').first().json;

return [{
  json: {
    ...prev,
    dataset_meta: {
      dimensions:                parsed.dimensions                || [],
      measures:                  parsed.measures                  || [],
      time_fields:               parsed.time_fields               || [],
      analytical_richness_score: parsed.analytical_richness_score || 50,
      warnings:                  parsed.warnings                  || [],
      row_count:                 prev.row_count
    }
  }
}];

