const raw = $input.first().json.output || '';
let parsed = {};
try {
  const cleaned = raw.replace(/```json?\n?/gi, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { tabs: {} };
}

const prev = $('Parse — Agent 3 Output').first().json;

const defaultTab = (label) => ({
  label,
  description: '',
  kpi_ids: [],
  chart_ids: [],
  layout: []
});

const tabs = parsed.tabs || {};

return [{
  json: {
    ...prev,
    tabs: {
      c_suite:           tabs.c_suite           || defaultTab('C-Suite / Leaders'),
      top_management:    tabs.top_management    || defaultTab('Top Management'),
      middle_management: tabs.middle_management || defaultTab('Middle Management'),
      end_users:         tabs.end_users         || defaultTab('End Users')
    }
  }
}];

const raw = $input.first().json.output || '';
let layoutData = { layouts: {} };
try {
  const cleaned = raw.replace(/```json?\n?/gi, '').replace(/```/g, '').trim();
  layoutData = JSON.parse(cleaned);
} catch (e) {
  // Layout parse failed — fall back to auto-layout below
}

const prev = $('Parse — Agent 4 Output').first().json;
const layouts = layoutData.layouts || {};

// Merge AI layouts into tabs (or auto-generate fallback layout)
const tabs = {};
for (const tabKey of ['c_suite', 'top_management', 'middle_management', 'end_users']) {
  const tab = prev.tabs[tabKey] || { label: tabKey, description: '', kpi_ids: [], chart_ids: [] };

  if (layouts[tabKey] && layouts[tabKey].length > 0) {
    tab.layout = layouts[tabKey];
  } else {
    // Auto-generate simple layout
    const kpiItems = (tab.kpi_ids || []).map((id, i) => ({
      id, type: 'kpi', col_span: 3, row_span: 1, order: i + 1
    }));
    const chartItems = (tab.chart_ids || []).map((id, i) => ({
      id, type: 'chart', col_span: 6, row_span: 2, order: kpiItems.length + i + 1
    }));
    tab.layout = [...kpiItems, ...chartItems];
  }

  tabs[tabKey] = tab;
}

// Assemble the complete dashboard spec
const dashboardSpec = {
  dashboard_id:  prev.dashboard_id,
  created_at:    new Date().toISOString(),
  domain:        prev.domain,
  business_goal: prev.business_goal,
  theme:         prev.theme || 'modern',
  dataset_meta:  prev.dataset_meta,
  global_filters: prev.global_filters || [],
  kpis:           prev.kpis     || [],
  charts:         prev.charts   || [],
  insights:       prev.insights || [],
  tabs,
  validation: {
    quality_score:           0,
    duplicates_removed:      0,
    hallucinations_detected: 0,
    invalid_charts_removed:  0,
    warnings:                []
  }
};

return [{ json: { dashboard_spec: dashboardSpec } }];
